css:
/* Base Settings for Old PDF Engines (wkhtmltopdf) */
.afmco-doc {
    font-family: 'Tahoma', 'Arial', sans-serif;
    font-size: 11px;
    direction: rtl;
    color: #333;
    line-height: 1.3;
    background: #fff;
}

/* Colors Variables (Hardcoded) */
/* Green: #00844E, Dark: #072B1A, Sand: #ECE6D6 */

/* Top Strip */
.brand-strip {
    height: 6px;
    background-color: #00844E;
    margin-bottom: 20px;
    width: 100%;
}

/* Header */
.header-table { margin-bottom: 25px; }
.logo-side { text-align: right; }
.title-side { 
    text-align: left; 
    padding-left: 15px; 
    border-left: 3px solid #ECE6D6; 
}
.main-title {
    font-size: 24px;
    color: #072B1A;
    margin: 0;
    font-weight: bold;
}
.sub-title {
    font-size: 12px;
    color: #00844E;
    letter-spacing: 2px;
    margin-bottom: 10px;
    font-weight: bold;
}

/* Reference Table in Header */
.ref-table { width: auto; margin-left: 0; }
.ref-lbl { 
    font-size: 10px; 
    color: #666; 
    padding-right: 5px; 
    text-align: left; 
    font-weight: bold;
}
.ref-val { 
    font-size: 11px; 
    color: #000; 
    font-weight: bold; 
    text-align: left;
}

/* Client Section */
.client-section { margin-bottom: 20px; }
.client-box {
    background-color: #F9F9F9;
    border-right: 4px solid #00844E;
    padding: 10px;
    vertical-align: top;
}
.validity-box {
    background-color: #ECE6D6;
    padding: 10px;
    text-align: center;
    border-radius: 4px;
}
.box-head {
    font-size: 9px;
    color: #666;
    text-transform: uppercase;
    margin-bottom: 4px;
}
.client-name {
    font-size: 13px;
    font-weight: bold;
    color: #072B1A;
    margin-bottom: 2px;
}
.client-address { font-size: 10px; color: #555; }
.valid-date { font-size: 12px; font-weight: bold; color: #00844E; }
.status-txt { font-size: 11px; font-weight: bold; color: #333; }

/* Items Table - The Core Design */
.items-container { margin-bottom: 20px; }
.items-table { 
    width: 100%; 
    border-collapse: collapse; 
    border-bottom: 2px solid #00844E;
}

/* Header Styling - High Contrast */
.items-table thead th {
    background-color: #072B1A !important;
    color: #ffffff !important;
    font-size: 10px;
    padding: 8px 5px;
    border: 1px solid #072B1A;
    font-weight: bold;
    -webkit-print-color-adjust: exact; /* Crucial for PDF */
    print-color-adjust: exact;
}
.en-th {
    font-size: 8px;
    font-weight: normal;
    color: #ddd;
    display: block;
    margin-top: 2px;
}

/* Cells */
.items-table tbody td {
    padding: 8px 5px;
    border-bottom: 1px solid #eee;
    border-left: 1px solid #eee;
    border-right: 1px solid #eee;
    vertical-align: middle;
}
/* Alternating Rows */
.items-table tbody tr:nth-child(even) td {
    background-color: #f7f7f7 !important;
    -webkit-print-color-adjust: exact;
}

/* Column alignments */
.th-c, .td-c { text-align: center; }
.th-r, .td-r { text-align: right; }
.th-l, .td-l { text-align: left; direction: ltr; } /* LTR for Money */

.desc-cell { line-height: 1.4; }
.it-ar { font-weight: bold; color: #000; font-size: 11px; }
.it-en { font-size: 10px; color: #666; direction: ltr; text-align: left; margin-top: 2px; }

.num-font { font-family: monospace; font-size: 11px; }
.bold-num { font-weight: bold; color: #000; }

/* Totals Area */
.totals-area { margin-bottom: 15px; page-break-inside: avoid; }
.words-box {
    background: #f0f0f0;
    padding: 6px;
    border-radius: 4px;
    margin-bottom: 8px;
    font-size: 10px;
}
.w-lbl { color: #666; }
.w-val { font-weight: bold; color: #00844E; }

.sys-terms { font-size: 9px; color: #666; line-height: 1.4; }
.sys-terms p { margin: 2px 0; }
.sys-terms img { max-width: 100px; height: auto; } /* Control Bank Image size */

.sum-table td { padding: 5px; border-bottom: 1px solid #eee; }
.sum-lbl { text-align: left; color: #555; font-size: 11px; font-weight: bold; }
.sum-val { text-align: right; color: #000; font-size: 12px; font-family: monospace; direction: ltr; }

/* Grand Total Row */
.grand-row td {
    background-color: #00844E !important;
    color: #ffffff !important;
    padding: 8px;
    border: none;
    -webkit-print-color-adjust: exact;
}
.grand-row .sum-lbl { color: #fff; font-size: 12px; }
.grand-row .sum-val { color: #fff; font-size: 14px; font-weight: bold; }
.curr { font-size: 9px; margin-left: 3px; font-weight: normal; opacity: 0.8; }

/* Static Terms */
.static-terms { 
    border-top: 1px solid #ccc; 
    padding-top: 10px; 
    margin-bottom: 20px; 
    page-break-inside: avoid;
}
.terms-head { font-weight: bold; font-size: 11px; margin-bottom: 5px; color: #072B1A; }
.static-terms ul { margin: 0; padding-right: 15px; padding-left: 0; }
.static-terms li { margin-bottom: 3px; font-size: 9px; color: #444; }
.t-en { direction: ltr; text-align: left; }
.t-en ul { padding-right: 0; padding-left: 15px; }

/* Signatures */
.sign-table { page-break-inside: avoid; }
.s-head { font-weight: bold; font-size: 11px; color: #072B1A; margin-bottom: 40px; text-align: center; }
.s-box { border-bottom: 1px solid #000; width: 80%; margin: 0 auto; height: 1px; }

/* Print Fixes */
@media print {
    body { margin: 0; padding: 0; }
    .items-table thead th, .grand-row td { -webkit-print-color-adjust: exact; }
}
